 * Restore focus to the opener element (the element that had focus before a dialog opened).
 * @param {Element} opener - The element to focus.
 */
export function restoreFocusToOpener(opener) {
  if (opener && typeof opener.focus === 'function') {
    opener.focus()
  }
}

